package com.gamehub;

import com.gamehub.application.OperationsService;
import com.gamehub.application.UserService;
import com.gamehub.domain.User;
import com.gamehub.infrastructure.Database;
import javafx.application.Application;
import javafx.collections.FXCollections;
import javafx.geometry.Insets;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Map;

/** JavaFX presentation layer for the twelve GameHub workflows. */
public final class GameHubApp extends Application {
  private Database db; private UserService users; private OperationsService ops; private Stage stage; private User current; private Label feedback;
  @Override public void start(Stage s){stage=s;try{db=new Database();users=new UserService(db);ops=new OperationsService(db);showLogin();}catch(Exception e){showError("Database startup failed",e);}}
  private void showLogin(){TextField u=new TextField();u.setPromptText("Username or email");PasswordField p=new PasswordField();p.setPromptText("Password (8+ characters)");feedback=new Label("Enter your credentials and select Sign in.");Button in=new Button("Sign in");in.setDefaultButton(true);Work signIn=()->{User x=users.authenticate(u.getText(),p.getText());if(x==null){feedback.setText("Invalid username or password.");throw new IllegalArgumentException("Invalid username or password");}current=x;showWorkspace();};in.setOnAction(e->{try{signIn.run();}catch(Exception ex){new Alert(Alert.AlertType.WARNING,"Sign in failed\n"+ex.getMessage()).showAndWait();}});u.setOnAction(e->p.requestFocus());p.setOnAction(e->in.fire());Button reg=new Button("Create customer account");reg.setOnAction(e->registrationForm());Button mgr=new Button("First-time manager setup");mgr.setOnAction(e->managerSetup());VBox box=new VBox(12,new Label("GAMEHUB"),new Label("Gaming café and tournament operations"),u,p,in,reg,mgr,feedback);box.setPadding(new Insets(36));box.setMaxWidth(480);stage.setTitle("GameHub");Scene loginScene=new Scene(new StackPane(box),700,520);loginScene.getStylesheets().add(getClass().getResource("/gamehub.css").toExternalForm());stage.setScene(loginScene);stage.show();}
  private void registrationForm(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Create Customer Account");GridPane g=formGrid();TextField n=new TextField(),e=new TextField(),ph=new TextField();PasswordField p=new PasswordField(),c=new PasswordField();g.addRow(0,new Label("Full name"),n);g.addRow(1,new Label("Email"),e);g.addRow(2,new Label("Phone"),ph);g.addRow(3,new Label("Password"),p);g.addRow(4,new Label("Confirm password"),c);d.getDialogPane().setContent(g);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);d.showAndWait().filter(x->x==ButtonType.OK).ifPresent(x->run("Registration",()->{if(!p.getText().equals(c.getText()))throw new IllegalArgumentException("Passwords do not match");users.registerCustomer(n.getText(),e.getText(),ph.getText(),p.getText());feedback.setText("Account created. Sign in with your email.");}));}
  private void managerSetup(){TextInputDialog u=new TextInputDialog();u.setHeaderText("Manager username");u.showAndWait().ifPresent(n->{TextInputDialog p=new TextInputDialog();p.setHeaderText("Manager password");p.showAndWait().ifPresent(x->run("Manager setup",()->{users.bootstrap(n,x);feedback.setText("Manager created. Sign in.");}));});}
  private void showWorkspace(){
    Map<String,Pane> pages=new java.util.LinkedHashMap<>();
    pages.put("Dashboard",home()); pages.put("Customers / Accounts",registrationTab()); pages.put("Reservations",reservationTab());
    if(!current.role().name().equals("CUSTOMER")){pages.put("Gaming Sessions",sessionTab()); pages.put("Payments & Receipts",paymentTab());} pages.put("Memberships",membershipTab());
    pages.put("Gaming Teams",teamTab()); pages.put("Tournaments",tournamentRegistrationTab());
    if(isManager()){pages.put("Tournament Management",tournamentManagementTab());pages.put("Matches",matchesTab());pages.put("Gaming Stations",stationTab());pages.put("Maintenance",maintenanceTab());pages.put("Reports",reportsTab());} else if(isStaff()){pages.put("Maintenance",maintenanceTab());}
    StackPane workspace=new StackPane(); Label title=new Label(); title.getStyleClass().add("page-title"); Label role=new Label(current.username()+"  •  "+current.role().name()); role.getStyleClass().add("user-badge");
    HBox header=new HBox(18,title,new Region(),role); HBox.setHgrow(header.getChildren().get(1),Priority.ALWAYS); header.getStyleClass().add("top-header");
    VBox nav=new VBox(6); nav.getStyleClass().add("sidebar"); Label brand=new Label("GAMEHUB"); brand.getStyleClass().add("brand"); Label subtitle=new Label("Gaming operations"); subtitle.getStyleClass().add("sidebar-subtitle"); nav.getChildren().addAll(brand,subtitle);
    for(Map.Entry<String,Pane> entry:pages.entrySet()){Button b=new Button(entry.getKey());b.getStyleClass().add("nav-button");b.setMaxWidth(Double.MAX_VALUE);b.setOnAction(e->{title.setText(entry.getKey());workspace.getChildren().setAll(new ScrollPane(entry.getValue()));nav.getChildren().forEach(n->n.getStyleClass().remove("nav-selected"));b.getStyleClass().add("nav-selected");});nav.getChildren().add(b);}
    Region spacer=new Region();VBox.setVgrow(spacer,Priority.ALWAYS);Button settings=new Button("⚙  Settings");settings.getStyleClass().add("nav-button");settings.setOnAction(e->new Alert(Alert.AlertType.INFORMATION,"Signed in as "+current.username()+"\nRole: "+current.role().name()+"\nDatabase: %USERPROFILE%\\.gamehub\\gamehub.db").showAndWait());Button logout=new Button("⇥  Sign out");logout.getStyleClass().addAll("nav-button","nav-danger");logout.setOnAction(e->{current=null;showLogin();});nav.getChildren().addAll(spacer,settings,logout);
    BorderPane root=new BorderPane();root.setLeft(nav);root.setTop(header);root.setCenter(workspace);feedback=new Label("Ready");feedback.getStyleClass().add("status-feedback");feedback.setMaxWidth(Double.MAX_VALUE);root.setBottom(new StackPane(feedback));BorderPane.setMargin(header,new Insets(0,24,0,24));
    stage.setMinWidth(980);stage.setMinHeight(650);stage.setTitle("GameHub • Operations");stage.setScene(new Scene(root,1280,820));stage.getScene().getStylesheets().add(getClass().getResource("/gamehub.css").toExternalForm());
    Map.Entry<String,Pane> first=pages.entrySet().iterator().next();title.setText(first.getKey());workspace.getChildren().setAll(new ScrollPane(first.getValue()));((Button)nav.getChildren().get(2)).getStyleClass().add("nav-selected");stage.show();
  }
  @FunctionalInterface private interface Work { void run() throws Exception; }
  private boolean isManager(){return current!=null && current.role()==com.gamehub.domain.Role.MANAGER;} private boolean isStaff(){return current!=null && (current.role()==com.gamehub.domain.Role.STAFF||isManager());} private Tab tab(String n,Pane p){Tab t=new Tab(n,p);t.setClosable(false);return t;} private VBox page(String s){VBox v=new VBox(10);v.setPadding(new Insets(18));Label heading=new Label(s);heading.getStyleClass().add("page-title");v.getChildren().add(heading);return v;} private GridPane formGrid(){GridPane g=new GridPane();g.setHgap(10);g.setVgap(8);return g;} private TextField field(String p){TextField f=new TextField();f.setPromptText(p);return f;} private ListView<String> list(){ListView<String> l=new ListView<>();l.setPrefHeight(220);return l;} private Button action(String s,Work r){Button b=new Button(s);b.setOnAction(e->run(s,r));return b;} private void run(String op,Work r){try{r.run();if(feedback!=null)feedback.setText(op+" completed");}catch(Exception e){if(feedback!=null)feedback.setText(op+" failed: "+(e.getMessage()==null?e:e.getMessage()));}} private void showError(String s,Exception e){new Alert(Alert.AlertType.ERROR,s+"\n"+e.getMessage()).showAndWait();} private Instant instant(String s,Instant d){return s==null||s.isBlank()?d:Instant.parse(s.trim());} private long selectedId(String s){if(s==null||!s.trim().startsWith("#"))throw new IllegalArgumentException("Select a record first");return Long.parseLong(s.trim().substring(1).split("\\s+|\\|")[0]);}
  private Pane home(){VBox v=page("Operations dashboard");GridPane cards=new GridPane();cards.setHgap(14);cards.setVgap(14);TextArea activity=new TextArea();activity.setEditable(false);activity.setPrefRowCount(8);Work refresh=()->{try{Map<String,Long> m=ops.reportCounts();cards.getChildren().clear();int col=0,row=0;for(String key:java.util.List.of("gaming_stations","reservations","sessions","payments","tournaments","maintenance")){VBox card=new VBox(5,new Label(key.replace('_',' ').toUpperCase()),new Label(String.valueOf(m.getOrDefault(key,0L))));card.getStyleClass().add("stat-card");cards.add(card,col++,row);if(col==3){col=0;row++;}}activity.setText("Live database counts refreshed at "+java.time.LocalDateTime.now());}catch(Exception e){activity.setText("Unable to refresh dashboard: "+e.getMessage());}};Button refreshButton=action("Refresh live data",refresh);try{refresh.run();}catch(Exception ignored){}v.getChildren().addAll(new Label("Welcome back, "+current.username()+". Monitor the gaming center from one workspace."),cards,new Label("System status"),activity,refreshButton);return v;}
  private Pane registrationTab(){VBox v=page("Create customer account");v.getChildren().add(action("Open registration form",this::registrationForm));return v;}
  private Pane reservationTab(){VBox v=page("Reserve a Gaming Station");DatePicker startDate=new DatePicker(java.time.LocalDate.now().plusDays(1)),endDate=new DatePicker(java.time.LocalDate.now().plusDays(1));TextField startTime=field("Start time HH:mm"),endTime=field("End time HH:mm");startTime.setText("10:00");endTime.setText("12:00");ListView<String> rows=list();Label hint=new Label("Choose an available station, then confirm.");java.time.ZoneId zone=java.time.ZoneId.of("Asia/Karachi");java.util.function.Supplier<Instant[]> interval=()->{try{java.time.LocalDateTime a=java.time.LocalDateTime.of(startDate.getValue(),java.time.LocalTime.parse(startTime.getText()));java.time.LocalDateTime b=java.time.LocalDateTime.of(endDate.getValue(),java.time.LocalTime.parse(endTime.getText()));return new Instant[]{a.atZone(zone).toInstant(),b.atZone(zone).toInstant()};}catch(Exception e){throw new IllegalArgumentException("Use valid Karachi dates and HH:mm times");}};Button find=action("Find available stations",()->{Instant[] x=interval.get();rows.setItems(FXCollections.observableArrayList(ops.availableStations(x[0],x[1],null)));hint.setText(rows.getItems().isEmpty()?"No stations are available for this interval.":"Select a station from the results.");});Button book=action("Confirm reservation",()->{String selected=rows.getSelectionModel().getSelectedItem();long station=selectedId(selected);Instant[] x=interval.get();long id=ops.reserve(current.id(),station,x[0],x[1]);hint.setText("Reservation #"+id+" confirmed.");rows.setItems(FXCollections.observableArrayList(ops.reservations(current.id())));});TextField cancel=field("Reservation id");v.getChildren().addAll(new HBox(8,new Label("Date"),startDate,new Label("Start"),startTime,new Label("End date"),endDate,new Label("End"),endTime),new HBox(8,find,book),hint,new Label("Available stations / your reservations"),rows,new HBox(8,cancel,action("Cancel reservation",()->{ops.cancelReservation(current.id(),Long.parseLong(cancel.getText()));rows.setItems(FXCollections.observableArrayList(ops.reservations(current.id())));}),action("Refresh my reservations",()->rows.setItems(FXCollections.observableArrayList(ops.reservations(current.id()))))));return v;}
  private Pane sessionTab(){VBox v=page("Conduct a Gaming Session");TextField r=field("Reservation id"),s=field("Session id");v.getChildren().addAll(new HBox(8,r,action("Start session",()->s.setText(""+ops.startSession(current.id(),Long.parseLong(r.getText()))))),new HBox(8,s,action("Finish session and calculate bill",()->ops.finishSessionCalculated(current.id(),Long.parseLong(s.getText())))));return v;}
  private Pane paymentTab(){VBox v=page("Process a Payment");ListView<String> charges=list();TextField a=field("Amount paisa"),ref=field("Unique reference");ComboBox<String> m=new ComboBox<>(FXCollections.observableArrayList("CASH","MANUAL_EXTERNAL"));m.getSelectionModel().selectFirst();Button refresh=action("Refresh outstanding charges",()->charges.setItems(FXCollections.observableArrayList(ops.outstandingCharges())));Label receipt=new Label();Button pay=action("Settle selected charge",()->{long id=selectedId(charges.getSelectionModel().getSelectedItem());long payment=ops.payChargeAsStaff(current.id(),id,Long.parseLong(a.getText()),m.getValue(),ref.getText());receipt.setText("Payment recorded. Receipt GH-"+payment);refresh.fire();});v.getChildren().addAll(new HBox(8,refresh),charges,new HBox(8,a,m,ref,pay),receipt);return v;}
  private Pane membershipTab(){VBox v=page("Subscribe or Renew Membership");ComboBox<String> p=new ComboBox<>();Label out=new Label();Button refresh=action("Refresh plans and status",()->{try{p.setItems(FXCollections.observableArrayList(ops.membershipPlans().stream().map(x->x.split(" \\|")[0]).toList()));if(!p.getItems().isEmpty())p.getSelectionModel().selectFirst();out.setText("Current membership: "+ops.membership(current.id()));}catch(Exception e){throw new RuntimeException(e);}});v.getChildren().addAll(new HBox(8,refresh),p,action("Subscribe or renew selected plan",()->{ops.subscribeOrRenew(current.id(),p.getValue());out.setText("Membership updated: "+ops.membership(current.id()));}),out);return v;}
  private Pane teamTab(){VBox v=page("Gaming Teams");TextField n=field("New team name");ListView<String> teams=list(),requests=list();Button refresh=action("Refresh teams",()->teams.setItems(FXCollections.observableArrayList(ops.teams())));Button create=action("Create team",()->{ops.createTeam(current.id(),n.getText());refresh.fire();});Button request=action("Request to join selected team",()->ops.requestJoin(selectedId(teams.getSelectionModel().getSelectedItem()),current.id()));Button refreshRequests=action("Refresh captain requests",()->requests.setItems(FXCollections.observableArrayList(ops.teamRequests(current.id()))));Button approve=action("Approve selected request",()->{String x=requests.getSelectionModel().getSelectedItem();if(x==null)throw new IllegalArgumentException("Select a pending request");long team=Long.parseLong(x.substring(1).split(" \\|")[0]);long member=Long.parseLong(x.substring(x.indexOf("#",1)+1).split(" ")[0]);ops.decideJoin(current.id(),team,member,true);refreshRequests.fire();});v.getChildren().addAll(new HBox(8,n,create),new Label("Available teams"),new HBox(8,refresh,request),teams,new Label("Captain pending requests"),new HBox(8,refreshRequests,approve),requests);return v;}
  private Pane tournamentRegistrationTab(){VBox v=page("Register for a Tournament");TextField id=field("Tournament id");v.getChildren().add(new HBox(8,id,action("Register",()->ops.registerTournament(Long.parseLong(id.getText()),current.id()))));return v;}
  private Pane tournamentManagementTab(){VBox v=page("Manage Tournaments");TextField n=field("Name"),fee=field("Fee paisa"),id=field("Tournament id");ComboBox<String>f=new ComboBox<>(FXCollections.observableArrayList("SINGLE_ELIMINATION","ROUND_ROBIN"));f.getSelectionModel().selectFirst();ComboBox<String>s=new ComboBox<>(FXCollections.observableArrayList("REGISTRATION_CLOSED","ACTIVE","COMPLETED","CANCELLED"));v.getChildren().addAll(new HBox(8,n,f,fee,action("Create tournament",()->ops.createTournament(current.id(),n.getText(),f.getValue(),Long.parseLong(fee.getText())))),new HBox(8,id,s,action("Change status",()->ops.changeTournamentStatus(current.id(),Long.parseLong(id.getText()),s.getValue()))));return v;}
  private Pane matchesTab(){VBox v=page("Conduct Tournament Matches");TextField t=field("Tournament id"),startMatchId=field("Selected match id"),resultMatchId=field("Selected match id"),a=field("Score A"),b=field("Score B"),w=field("Winner registration id");ListView<String> rows=list();Button refresh=action("Refresh matches",()->rows.setItems(FXCollections.observableArrayList(ops.matches(Long.parseLong(t.getText())))));v.getChildren().addAll(new HBox(8,t,action("Generate bracket",()->{ops.generateMatches(current.id(),Long.parseLong(t.getText()));rows.setItems(FXCollections.observableArrayList(ops.matches(Long.parseLong(t.getText()))));})),rows,new HBox(8,startMatchId,action("Start match",()->ops.startMatch(current.id(),Long.parseLong(startMatchId.getText()))),refresh),new HBox(8,resultMatchId,a,b,w,action("Record result",()->ops.recordMatchResult(current.id(),Long.parseLong(resultMatchId.getText()),Integer.parseInt(a.getText()),Integer.parseInt(b.getText()),Long.parseLong(w.getText())))));return v;}
  private Pane stationTab(){VBox v=page("Manage Gaming Stations");TextField code=field("Code"),type=field("Type"),spec=field("Specs"),rate=field("Hourly rate paisa"),id=field("Station id");ListView<String> rows=list();v.getChildren().addAll(new HBox(8,code,type,spec,rate,action("Add station",()->{ops.addStation(current.id(),code.getText(),type.getText(),spec.getText(),Long.parseLong(rate.getText()));rows.setItems(FXCollections.observableArrayList(ops.stations()));})),new HBox(8,id,action("Deactivate station",()->ops.deactivateStation(current.id(),Long.parseLong(id.getText()))),action("Refresh",()->rows.setItems(FXCollections.observableArrayList(ops.stations())))),rows);return v;}
  private Pane maintenanceTab(){VBox v=page("Equipment Maintenance");ListView<String> stations=list(),tickets=list();TextField desc=field("Description"),notes=field("Resolution notes");ComboBox<String> sev=new ComboBox<>(FXCollections.observableArrayList("LOW","MEDIUM","HIGH","CRITICAL"));sev.getSelectionModel().select("MEDIUM");Button refreshStations=action("Refresh stations",()->stations.setItems(FXCollections.observableArrayList(ops.stationRecords())));Button refreshTickets=action("Refresh tickets",()->tickets.setItems(FXCollections.observableArrayList(ops.maintenanceTickets())));Button report=action("Report maintenance",()->{ops.openMaintenance(current.id(),selectedId(stations.getSelectionModel().getSelectedItem()),sev.getValue(),desc.getText());refreshStations.fire();refreshTickets.fire();});Button progress=action("Mark in progress",()->{ops.updateMaintenance(current.id(),selectedId(tickets.getSelectionModel().getSelectedItem()),"IN_PROGRESS",notes.getText(),false);refreshTickets.fire();});Button resolve=action("Resolve and mark ready",()->{ops.updateMaintenance(current.id(),selectedId(tickets.getSelectionModel().getSelectedItem()),"RESOLVED",notes.getText(),true);refreshStations.fire();refreshTickets.fire();});v.getChildren().addAll(new HBox(8,refreshStations),stations,new HBox(8,sev,desc,report),new HBox(8,refreshTickets),tickets,new HBox(8,notes,progress,resolve));return v;}
  private Pane reportsTab(){VBox v=page("Management Reports");TextArea out=new TextArea();out.setEditable(false);v.getChildren().addAll(action("Refresh report",()->{Map<String,Long>m=ops.reportCounts();out.setText(m.entrySet().stream().map(e->e.getKey()+": "+e.getValue()).reduce((x,y)->x+"\n"+y).orElse("No data"));}),out);return v;}
  @Override public void stop(){try{if(db!=null)db.close();}catch(Exception ignored){}} public static void main(String[]a){launch(a);}
}








